 tool('forge_preview_capture','Capture actual native preview PNGs from the connected page, including current material camera/light/roughness or effect background/blend comparison. Returns one image for canvas/material or up to four effect tiles with settings and source revision. Does not edit project data; selects no other page and does not change preview mode. Use forge_editor_control to choose a view first. Material/effect frames are square at size 128..1024 (default512), independent of dock panel dimensions; current on-screen dimensions are restored immediately.',{pageId:z.string().uuid(),size:z.number().int().min(128).max(1024).default(512)},async({pageId,size},extra)=>{
  const result=await bridge.request(pageId,'preview-capture',{args:{size},signal:extra.signal});if(!Array.isArray(result.frames)||result.frames.length<1||result.frames.length>4)throw Error('Invalid preview frames');
  const directory=resolve(await service.directory(),'preview-'+randomUUID());await mkdir(directory);const files=[],content=[];
  for(const [i,frame]of result.frames.entries()){if(typeof frame.data!=='string'||frame.data.length>24000000||!/^[A-Za-z0-9+/]+={0,2}$/.test(frame.data))throw Error('Invalid preview image');const bytes=Buffer.from(frame.data,'base64');if(bytes.subarray(1,4).toString()!=='PNG')throw Error('Expected PNG preview');const file=resolve(directory,'preview-'+i+'.png');await writeFile(file,bytes,{flag:'wx'});const {data,...metadata}=frame;files.push({...metadata,file,bytes:bytes.length,sha256:digest(bytes)});content.push({type:'image',data:frame.data,mimeType:'image/png'});}
  const {frames,...metadata}=result,data={...metadata,files};return {...textResult(data),content:[{type:'text',text:JSON.stringify(data)},...content]};
 });
