// Stateless HTTP requests have independent SDK transports; project snapshots live in
// the shared service, never in an agent's transport or mutable "selected page".
export function createEditorMCP(options={}){
 let service;const active=new Set();
 const bridge=new EditorBridge({...options,onDisconnect:pageId=>service?.clear(pageId),onMCP:async(req,res)=>{
  if(req.method!=='POST'){res.setHeader('Allow','POST');bridge.reply(res,405,{error:'Use Streamable HTTP POST'});return;}
  if(active.size>=32){bridge.reply(res,429,{error:'Too many concurrent MCP requests'});return;}
  const server=createEditorMCPServer(bridge,service),transport=new StreamableHTTPServerTransport({sessionIdGenerator:undefined,enableJsonResponse:true});active.add(server);
  const close=()=>{active.delete(server);void server.close();};res.once('close',close);
  try{const body=await readBridgeJSON(req,1024*1024);await server.connect(transport);await transport.handleRequest(req,res,body);}catch(error){close();throw error;}
 }});
 service=new LiveProjectService(bridge,options);
 return {bridge,service,start:()=>bridge.start(),async close(){await bridge.close();await service.exports.tail;await Promise.all([...active].map(server=>server.close()));active.clear();}};
}
export async function editorAgentToken(directory=join(homedir(),'.momo-texture-forge')){
 await mkdir(directory,{recursive:true});const file=join(directory,'mcp-token');
 try{const token=(await readFile(file,'utf8')).trim();if(!/^[A-Za-z0-9_-]{43}$/.test(token))throw Error('Invalid local MCP credential file');return token;}catch(error){if(error.code!=='ENOENT')throw error;}
 const token=bridgeSecret(),temporary=join(directory,'mcp-token-'+randomUUID());await writeFile(temporary,token+'\n',{mode:0o600,flag:'wx'});
 try{await link(temporary,file);}catch(error){if(error.code!=='EEXIST')throw error;}finally{await rm(temporary,{force:true});}
 return (await readFile(file,'utf8')).trim();
}
export async function startEditorMCP(options={}){
 const app=createEditorMCP({...options,agentToken:options.agentToken??await editorAgentToken()});await app.start();return app;
}
export async function serveEditorMCP(args){
 const app=await startEditorMCP(editorMCPOptions(args));
 console.log('Texture Forge MCP: http://127.0.0.1:'+app.bridge.port+'/mcp — enable MCP in the editor, then copy its connection configuration.');
 let stopping=false;const stop=async()=>{if(stopping)return;stopping=true;await app.close();};
 process.once('SIGINT',stop);process.once('SIGTERM',stop);return app;
}
